import test from 'node:test';
import assert from 'node:assert/strict';
import { mergeCustomers } from '../src/customers.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('mergeCustomers merges invoices from one customer to another', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const r = mergeCustomers(customers, [issued1.value, issued2.value], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  // Customer C-001 should be gone
  assert.equal(r.value.customers.length, 1);
  assert.equal(r.value.customers[0].id, 'C-002');
  // Both invoices should now belong to C-002
  assert.equal(r.value.invoices.length, 2);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
  assert.equal(r.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers rejects same customer', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
  ];

  const r = mergeCustomers(customers, [], 'C-001', 'C-001');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers rejects unknown from customer', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const r = mergeCustomers(customers, [], 'C-999', 'C-002');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects unknown into customer', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const r = mergeCustomers(customers, [], 'C-001', 'C-999');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers handles normalized customer IDs', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const invoice1 = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const r = mergeCustomers(customers, [issued1.value], ' c-001 ', 'C-002');
  assert.equal(r.ok, true);
  // Should successfully merge using normalized IDs
  assert.equal(r.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers does not mutate input arrays', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const originalCustomersLength = customers.length;
  const originalInvoicesLength = [issued1.value].length;

  mergeCustomers(customers, [issued1.value], 'C-001', 'C-002');

  // Original arrays should be unchanged
  assert.equal(customers.length, originalCustomersLength);
  assert.equal(customers[0].id, 'C-001'); // Still has C-001
  assert.equal([issued1.value][0].customerId, 'C-001'); // Still assigned to C-001
});

test('mergeCustomers with empty invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const r = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
  assert.equal(r.value.customers.length, 1);
});

test('mergeCustomers with multiple invoices from from-customer', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const r = mergeCustomers(customers, [issued1.value, issued2.value], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 2);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
  assert.equal(r.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers preserves invoices for other customers', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
    { id: 'C-003', name: 'Gamma', email: 'info@gamma.example', tier: 'standard' },
  ];

  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const r = mergeCustomers(customers, [issued1.value, issued2.value], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  // C-003's invoice should stay with C-003
  assert.equal(r.value.invoices.find(inv => inv.number === 'INV-2026-0002').customerId, 'C-003');
});

test('mergeCustomers with draft invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });

  const r = mergeCustomers(customers, [draft.value], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].status, 'draft');
  assert.equal(r.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers with partially paid invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const partial = recordPayment(issued.value, { amount: 5000, date: '2026-10-10' });

  const r = mergeCustomers(customers, [partial.value], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].status, 'partially_paid');
  assert.equal(r.value.invoices[0].customerId, 'C-002');
  // Payment record should be preserved
  assert.equal(r.value.invoices[0].payments.length, 1);
});

test('mergeCustomers preserves customer properties', () => {
  const customers = [
    { id: 'C-001', name: 'Acme Corp', email: 'info@acme.example', country: 'US', tier: 'gold' },
    { id: 'C-002', name: 'Beta Ltd', email: 'info@beta.example', country: 'UK', tier: 'standard' },
  ];

  const r = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  // C-002 should still have all its properties
  const c002 = r.value.customers[0];
  assert.equal(c002.id, 'C-002');
  assert.equal(c002.name, 'Beta Ltd');
  assert.equal(c002.country, 'UK');
});

test('mergeCustomers with null arrays', () => {
  const r = mergeCustomers(null, null, 'C-001', 'C-002');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers preserves order of remaining customers', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
    { id: 'C-003', name: 'Gamma', email: 'info@gamma.example', tier: 'standard' },
  ];

  const r = mergeCustomers(customers, [], 'C-002', 'C-003');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 2);
  assert.equal(r.value.customers[0].id, 'C-001');
  assert.equal(r.value.customers[1].id, 'C-003');
});

test('mergeCustomers preserves invoice order', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
