test('mergeCustomers preserves invoice order', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'info@acme.example', tier: 'gold' },
    { id: 'C-002', name: 'Beta', email: 'info@beta.example', tier: 'standard' },
  ];

  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const invoice3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-09',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued3 = issueInvoice(invoice3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const r = mergeCustomers(
    customers,
    [issued1.value, issued2.value, issued3.value],
    'C-001',
    'C-002'
  );
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 3);
  // Invoices should maintain their order
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(r.value.invoices[1].number, 'INV-2026-0002');
  assert.equal(r.value.invoices[2].number, 'INV-2026-0003');
  // First and third should now belong to C-002
  assert.equal(r.value.invoices[0].customerId, 'C-002');
  assert.equal(r.value.invoices[2].customerId, 'C-002');
});

